draw:
function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var R = p.radius / 100, I = p.current, z = p.z / 100, N = p.turns;
var mu = 4 * Math.PI * 1e-7;
var B = mu * N * I * R * R / (2 * Math.pow(R * R + z * z, 1.5));
var B0 = mu * N * I / (2 * R);

// left panel: the loop seen edge on
var ox = W * 0.26, oy = H * 0.5;
var sc = Math.min(W * 0.20 / Math.max(R, 0.01), H * 0.32 / Math.max(R, 0.01));
sc = Math.min(sc, H * 0.30 / Math.max(R, 0.01));
var rr = R * sc;
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(W * 0.46, oy); ctx.stroke();
ctx.fillStyle = C.faint; ctx.fillText("axis", W * 0.40, oy - 6);

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(ox, oy - rr, 5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(ox, oy + rr, 5, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.ellipse(ox, oy, rr * 0.30, rr, 0, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("loop, R = " + (R * 100).toFixed(0) + " cm", ox - 30, oy + rr + 20);

// field point on the axis
var zpix = Math.min(z * sc, W * 0.19);
var Px = ox + zpix;
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(Px, oy, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", Px + 6, oy - 8);
arrow(Px, oy, Px + 26, oy, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("B", Px + 30, oy + 4);

// the two elements whose sideways parts cancel
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]); ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ox, oy - rr); ctx.lineTo(Px, oy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ox, oy + rr); ctx.lineTo(Px, oy); ctx.stroke();
ctx.setLineDash([]);

// right panel: B against z
var gx = W * 0.56, gy = H * 0.16, gw = W * 0.38, gh = H * 0.62;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(gx, gy + gh); ctx.lineTo(gx + gw, gy + gh); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("B on the axis", gx, gy - 6);
ctx.fillText("z", gx + gw - 6, gy + gh + 16);

var zmax = 4 * R;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var zz = zmax * i / 120;
  var bb = (R * R * R) / Math.pow(R * R + zz * zz, 1.5);
  var gxx = gx + gw * (zz / zmax);
  var gyy = gy + gh - gh * bb;
  if (i === 0) { ctx.moveTo(gxx, gyy); } else { ctx.lineTo(gxx, gyy); }
}
ctx.stroke();

var frac = Math.min(z / zmax, 1);
var curB = (R * R * R) / Math.pow(R * R + z * z, 1.5);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(gx + gw * frac, gy + gh - gh * Math.min(curB, 1), 4, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.faint; ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(gx, gy + gh - gh * Math.min(curB, 1)); ctx.lineTo(gx + gw * frac, gy + gh - gh * Math.min(curB, 1)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("centre value", gx + 4, gy + 12);

out.note = "B = " + (B * 1e6).toFixed(2) + " microtesla at z = " + (z * 100).toFixed(0) + " cm, which is " + (100 * B / B0).toFixed(1) + " percent of the centre value " + (B0 * 1e6).toFixed(2) + " microtesla";
